class Solution {
public:
    int countSubarrays(std::vector<int>& nums, int k) {
        int n = nums.size();
        int pos = 0;
        for (int i = 0; i < n; ++i) if (nums[i] == k) { pos = i; break; }
        std::unordered_map<int, int> right_counts;
        int cur = 0;
        for (int i = pos; i < n; ++i) {
            if (nums[i] > k) cur++;
            else if (nums[i] < k) cur--;
            right_counts[cur]++;
        }
        cur = 0;
        int ans = 0;
        for (int i = pos; i >= 0; --i) {
            if (nums[i] > k) cur++;
            else if (nums[i] < k) cur--;
            ans += right_counts[-cur] + right_counts[1 - cur];
        }
        return ans;
    }
};

class Solution {
    public int countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int pos = 0;
        for (int i = 0; i < n; i++) if (nums[i] == k) { pos = i; break; }
        java.util.Map<Integer, Integer> rightCounts = new java.util.HashMap<>();
        int cur = 0;
        for (int i = pos; i < n; i++) {
            if (nums[i] > k) cur++;
            else if (nums[i] < k) cur--;
            rightCounts.put(cur, rightCounts.getOrDefault(cur, 0) + 1);
        }
        cur = 0;
        int ans = 0;
        for (int i = pos; i >= 0; i--) {
            if (nums[i] > k) cur++;
            else if (nums[i] < k) cur--;
            ans += rightCounts.getOrDefault(-cur, 0) + rightCounts.getOrDefault(1 - cur, 0);
        }
        return ans;
    }
}

